using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;
namespace FileCompass {
 internal sealed class DiskScanActivity {
  internal volatile string Path="",Operation="",LastError="";long last=DateTime.UtcNow.Ticks;internal long LastProgress{get{return Interlocked.Read(ref last);}}internal void Begin(string path,string operation){Path=path;Operation=operation;}internal void Progress(){Interlocked.Exchange(ref last,DateTime.UtcNow.Ticks);}
 }
 internal sealed partial class DiskAnalysis {
  internal string[] Roots;internal string RootDescription{get{return Roots==null?Root.Path:String.Join(Environment.NewLine,Roots);}}
  internal static string[] NormalizeRoots(IEnumerable<string> paths){var all=paths.Where(x=>!String.IsNullOrWhiteSpace(x)).Select(x=>{var full=System.IO.Path.GetFullPath(x.Trim()).TrimEnd('\\');return full.EndsWith(":",StringComparison.Ordinal)?full+"\\":full;}).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();return all.Where(x=>!all.Any(other=>!String.Equals(x,other,StringComparison.OrdinalIgnoreCase)&&DiskFileIndex.Within(x,other))).ToArray();}
  internal static DiskAnalysis ScanMany(string[] paths,CancellationToken token,DiskScanOptions options,Action<DiskAnalysis> update,DiskScanActivity activity){var roots=NormalizeRoots(paths);if(roots.Length==0)throw new IOException(L.Text("analyzer.noRoots"));if(roots.Length==1)return Scan(roots[0],token,null,null,options,update,activity);var results=new List<DiskAnalysis>();string index=options.StoreIndex?DiskFileIndex.CreatePath():null;try{using(var output=index==null?null:new FileStream(index,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){foreach(string root in roots){if(token.IsCancellationRequested)break;DiskAnalysis result=Scan(root,token,null,null,options,snapshot=>{if(update!=null)update(Merge(roots,results.Concat(new[]{snapshot}),index,true));},activity);results.Add(result);if(output!=null&&result.IndexPath!=null){using(var input=File.OpenRead(result.IndexPath))input.CopyTo(output);output.Flush();DiskFileIndex.Delete(result.IndexPath);}if(result.Cancelled)break;}}var merged=Merge(roots,results,index,false);merged.Cancelled=token.IsCancellationRequested;merged.IsPartial=merged.Cancelled;return merged;}catch{DiskFileIndex.Delete(index);foreach(var result in results)DiskFileIndex.Delete(result.IndexPath);throw;}}
  static DiskAnalysis Merge(string[] roots,IEnumerable<DiskAnalysis> results,string index,bool partial){var merged=new DiskAnalysis{Roots=roots,Root=new DiskFolder{Path=String.Join(" | ",roots),Virtual=true},IndexPath=index,ScannedUtc=DateTime.UtcNow,IsPartial=partial,FilterSignature="roots:"+String.Join("|",roots)};foreach(var result in results){var child=result.Root;child.Parent=merged.Root;merged.Root.Children.Add(child);merged.Root.Bytes+=child.Bytes;merged.Root.Files+=child.Files;merged.Folders+=result.Folders;merged.Skipped+=result.Skipped;merged.Issues.AddRange(result.Issues.Take(Math.Max(0,500-merged.Issues.Count)));merged.FilterSignature+="/"+result.FilterSignature;merged.FilterDescription=result.FilterDescription;foreach(var pair in result.Extensions)AddBucket(merged.Extensions,pair.Key,pair.Value);foreach(var pair in result.Categories)AddBucket(merged.Categories,pair.Key,pair.Value);for(int i=0;i<6;i++){merged.Ages[i].Bytes+=result.Ages[i].Bytes;merged.Ages[i].Files+=result.Ages[i].Files;merged.Sizes[i].Bytes+=result.Sizes[i].Bytes;merged.Sizes[i].Files+=result.Sizes[i].Files;}merged.Largest.AddRange(result.Largest);}merged.Largest.Sort((a,b)=>b.Bytes.CompareTo(a.Bytes));if(merged.Largest.Count>100)merged.Largest.RemoveRange(100,merged.Largest.Count-100);return merged;}
  static void AddBucket(Dictionary<string,DiskBucket> target,string key,DiskBucket source){DiskBucket bucket;if(!target.TryGetValue(key,out bucket))target[key]=bucket=new DiskBucket{Name=source.Name,Key=source.Key};bucket.Bytes+=source.Bytes;bucket.Files+=source.Files;}
  internal IEnumerable<DiskFolder> EmptyDirectories(){if(IsPartial)return Enumerable.Empty<DiskFolder>();var found=new List<DiskFolder>();var stack=new Stack<DiskFolder>();stack.Push(Root);while(stack.Count>0){var folder=stack.Pop();if(!folder.Virtual&&folder.ScanComplete&&!folder.SawEntries)found.Add(folder);foreach(var child in folder.Children)stack.Push(child);}return found;}
 }
}
